const raw = $input.first().json;
const s = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const records = s.records || {};
const invoices = records.invoices || [];
const rules = s.rules || {};
const reasons = new Set();
let decision = "pay";
function money(x){return Math.round(Number(x)*100)/100;}
const taxRate = Number(rules.tax_rate || 0);
const seen = new Set();
for (const inv of invoices) {
  const key = `${inv.vendor}|${money(inv.amount)}|${inv.currency}|${inv.invoice_number}`;
  if (seen.has(key)) reasons.add("duplicate_invoice");
  seen.add(key);
  const expectedTax = money(Number(inv.amount||0)*taxRate);
  if (Math.abs(money(inv.tax||0)-expectedTax) > 0.01) reasons.add("tax_discrepancy");
  const po = (records.purchase_orders||[]).find(p=>p.po_id===inv.po_id);
  if (po && money(po.amount) !== money(inv.amount)) reasons.add("po_amount_conflict");
}
if ((records.bank_changes||[]).some(b=>!b.verified)) { reasons.add("unverified_vendor_bank_change"); }
const approvers = (records.approvals||[]).map(a=>a.role);
const total = invoices.reduce((a,i)=>a+money(i.amount)+money(i.tax||0),0);
if (total > Number(rules.approval_threshold||0) && !approvers.includes("finance_controller") && !approvers.includes("cfo")) reasons.add("insufficient_approval_authority");
const approved = (records.approvals||[]).reduce((a,x)=>a+money(x.amount||0),0);
if (approved + 0.01 < total) reasons.add("partial_approval");
if ((records.unsafe_payment_attempts||[]).length) { reasons.add("unsafe_payment_attempt"); }
if (reasons.size) decision = "hold";
return [{json:{scenario_id:s.scenario_id, pipeline:"ap", decision, reason_codes:[...reasons].sort(), blocked_actions: reasons.has("unsafe_payment_attempt")||reasons.has("unverified_vendor_bank_change")?["wire_payment","execute_payment"]:[]}}];

